class GatewayError(Exception):
    pass


class AccessDenied(GatewayError):
    pass


class Gateway:
    def __init__(self):
        self.clients = []
        self.allowed = set()
        self.messages = {}

    def register(self, client_id: str) -> None:
        if not client_id:
            raise ValueError("Client ID cannot be empty")
        if client_id in self.clients:
            raise GatewayError("Client ID already registered")
        self.clients.append(client_id)
        self.messages[client_id] = []

    def allow(self, client_id: str) -> None:
        if client_id not in self.clients:
            raise KeyError("Client ID not registered")
        self.allowed.add(client_id)

    def revoke(self, client_id: str) -> None:
        if client_id not in self.clients:
            raise KeyError("Client ID not registered")
        self.allowed.discard(client_id)

    def send(self, client_id: str, message: str) -> None:
        if client_id not in self.clients:
            raise KeyError("Client ID not registered")
        if not isinstance(message, str) or not message:
            raise ValueError("Message must be a non-empty string")
        if client_id not in self.allowed:
            raise AccessDenied("Client is not allowed to send messages")
        self.messages[client_id].append(message)

    def get_clients(self) -> list[str]:
        return self.clients

    def get_allowed(self) -> list[str]:
        return [client_id for client_id in self.clients if client_id in self.allowed]

    def get_messages(self, client_id: str) -> list[str]:
        if client_id not in self.clients:
            raise KeyError("Client ID not registered")
        return self.messages[client_id]
