        if username in self.users:
            raise ChatError("User already exists")
        self.users[username] = []

    def join(self, username: str, room: str) -> None:
        if not isinstance(username, str) or not username:
            raise KeyError("Invalid username")
        if not isinstance(room, str) or not room:
            raise ValueError("Room name must be a non-empty string")
        if username not in self.users:
            raise KeyError("User not found")
        if room not in self.rooms:
            self.rooms[room] = []
            self.messages[room] = []
        if username in self.rooms[room]:
            raise ChatError("User is already in the room")
        self.rooms[room].append(username)

    def leave(self, username: str, room: str) -> None:
        if not isinstance(username, str) or not username:
            raise KeyError("Invalid username")
        if not isinstance(room, str) or not room:
            raise KeyError("Invalid room")
        if username not in self.users:
            raise KeyError("User not found")
        if room not in self.rooms:
            raise KeyError("Room not found")
        if username not in self.rooms[room]:
            raise ChatError("User is not in the room")
        self.rooms[room].remove(username)

    def post(self, username: str, room: str, text: str) -> None:
        if not isinstance(username, str) or not username:
            raise KeyError("Invalid username")
        if not isinstance(room, str) or not room:
            raise KeyError("Invalid room")
        if not isinstance(text, str) or not text:
            raise ValueError("Message text must be a non-empty string")
        if username not in self.users:
            raise KeyError("User not found")
        if room not in self.rooms:
            raise KeyError("Room not found")
        if username not in self.rooms[room]:
            raise ChatError("User is not a member of the room")
        self.messages[room].append((username, text))

    def get_members(self, room: str) -> list[str]:
        if not isinstance(room, str) or not room:
            raise KeyError("Invalid room")
        if room not in self.rooms:
            raise KeyError("Room not found")
        return self.rooms[room]

    def get_messages(self, room: str) -> list[tuple[str, str]]:
        if not isinstance(room, str) or not room:
            raise KeyError("Invalid room")
        if room not in self.rooms:
            raise KeyError("Room not found")
        return self.messages[room]

    def get_rooms(self) -> list[str]:
        return list(self.rooms.keys())
