        self.doctors = {}
        self.slots = {}
        self.bookings = {}

    def add_doctor(self, doctor: str) -> None:
        if not doctor:
            raise ValueError("Doctor name cannot be empty")
        if doctor in self.doctors:
            raise ClinicError(f"Doctor {doctor} already exists")
        self.doctors[doctor] = []

    def open_slot(self, doctor: str, day: int, minute: int) -> None:
        if not isinstance(doctor, str) or doctor not in self.doctors:
            raise KeyError(f"Unknown doctor: {doctor}")
        if not isinstance(day, int) or day < 1:
            raise ValueError("Invalid day")
        if not isinstance(minute, int) or not (0 <= minute <= 1439):
            raise ValueError("Invalid minute")
        if (doctor, day, minute) in self.slots:
            raise ClinicError(f"Slot {doctor} on day {day} at {minute} already exists")
        self.slots[(doctor, day, minute)] = None

    def book(self, doctor: str, day: int, minute: int, patient: str) -> None:
        if not isinstance(doctor, str) or doctor not in self.doctors:
            raise KeyError(f"Unknown doctor: {doctor}")
        if not isinstance(day, int) or day < 1:
            raise ValueError("Invalid day")
        if not isinstance(minute, int) or not (0 <= minute <= 1439):
            raise ValueError("Invalid minute")
        if not patient or not isinstance(patient, str):
            raise ValueError("Invalid patient")
        if (doctor, day, minute) not in self.slots or self.slots[(doctor, day, minute)] is not None:
            raise ClinicError(f"Slot {doctor} on day {day} at {minute} is not open for booking")
        self.slots[(doctor, day, minute)] = patient
        if patient not in self.bookings:
            self.bookings[patient] = []
        self.bookings[patient].append((doctor, day, minute))

    def get_open_slots(self, doctor: str, day: int) -> list[int]:
        if not isinstance(doctor, str) or doctor not in self.doctors:
            raise KeyError(f"Unknown doctor: {doctor}")
        if not isinstance(day, int) or day < 1:
            raise ValueError("Invalid day")
        return sorted(minute for (d, d_day, minute) in self.slots if d == doctor and d_day == day and self.slots[(d, d_day, minute)] is None)

    def get_appointments(self, patient: str) -> list[tuple[str, int, int]]:
        if not isinstance(patient, str) or not patient:
            raise ValueError("Invalid patient")
        return self.bookings.get(patient, [])

    def get_doctors(self) -> list[str]:
        return list(self.doctors.keys())
