            raise KeyError("Document ID not found")
        if tag not in self._documents[doc_id]['tags']:
            self._documents[doc_id]['tags'].append(tag)

    def get_title(self, doc_id: str) -> str:
        if doc_id not in self._documents:
            raise KeyError("Document ID not found")
