        if not isinstance(bucket, int) or not 0 <= bucket <= 99:
            raise ValueError("Invalid bucket")
        if user_id in self.users:
            raise FlagError("User already registered")
        self.users[user_id] = bucket

    def create_flag(self, name: str) -> None:
        if not isinstance(name, str) or not name:
            raise ValueError("Invalid flag name")
        if name in self.flags:
            raise FlagError("Flag already exists")
        self.flags[name] = {"rollout": 0, "enabled_users": set()}
        self.flag_order.append(name)

    def set_rollout(self, name: str, percent: int) -> None:
        if name not in self.flags:
            raise KeyError("Flag not found")
        if not isinstance(percent, int) or not 0 <= percent <= 100:
            raise ValueError("Invalid percent")
        self.flags[name]["rollout"] = percent

    def enable_for_user(self, name: str, user_id: str) -> None:
        if name not in self.flags:
            raise KeyError("Flag not found")
        if user_id not in self.users:
            raise KeyError("User not found")
        self.flags[name]["enabled_users"].add(user_id)

    def is_enabled(self, name: str, user_id: str) -> bool:
        if name not in self.flags:
            raise KeyError("Flag not found")
        if user_id not in self.users:
            raise KeyError("User not found")
        return user_id in self.flags[name]["enabled_users"] or \
               self.users[user_id] < self.flags[name]["rollout"]

    def get_enabled_users(self, name: str) -> list[str]:
        if name not in self.flags:
            raise KeyError("Flag not found")
        return [user_id for user_id in self.users if user_id in self.flags[name]["enabled_users"] or \
                self.users[user_id] < self.flags[name]["rollout"]]

    def get_flags(self) -> list[str]:
        return self.flag_order
