class GradebookError(Exception):
    pass


class Gradebook:
    def __init__(self):
        self.students = {}
        self.assignments = {}
        self.scores = {}

    def add_student(self, name: str) -> None:
        if not name:
            raise ValueError("Empty name")
        if name in self.students:
            raise GradebookError(f"Student '{name}' already exists")
        self.students[name] = {}

    def add_assignment(self, title: str, max_points: int) -> None:
        if not title:
            raise ValueError("Empty title")
        if not isinstance(max_points, int) or max_points <= 0:
            raise ValueError("Invalid max_points")
        if title in self.assignments:
            raise GradebookError(f"Assignment '{title}' already exists")
        self.assignments[title] = max_points

    def record_score(self, name: str, title: str, points: int) -> None:
        if name not in self.students:
            raise KeyError(f"Unknown student: {name}")
        if title not in self.assignments:
            raise KeyError(f"Unknown assignment: {title}")
        if not isinstance(points, int) or points < 0 or points > self.assignments[title]:
            raise ValueError("Invalid points")
        self.students[name][title] = points

    def get_score(self, name: str, title: str) -> int:
        if name not in self.students:
            raise KeyError(f"Unknown student: {name}")
        if title not in self.assignments:
            raise KeyError(f"Unknown assignment: {title}")
        if title not in self.students[name]:
            raise GradebookError(f"No score recorded for student '{name}' and assignment '{title}'")
        return self.students[name][title]

    def get_total(self, name: str) -> int:
        if name not in self.students:
            raise KeyError(f"Unknown student: {name}")
        return sum(self.students[name].values())

    def get_students(self) -> list[str]:
        return list(self.students.keys())

    def get_assignments(self) -> list[str]:
        return list(self.assignments.keys())
