        if not isinstance(word, str) or not word:
            raise ValueError("Word must be a non-empty string")
        if not word.islower() or not word.isalpha():
            raise ValueError("Word must consist only of lowercase letters")
        if game_id in self.games:
            raise HangmanError("Game ID already in use")
        self.games[game_id] = {
            'word': word,
            'guesses': set(),
            'wrong_guesses': 0,
            'status': 'playing'
        }
        self.game_ids.append(game_id)

    def guess(self, game_id: str, letter: str) -> bool:
        if game_id not in self.games:
            raise KeyError("Game ID not found")
