            raise RoomUnavailable("Room is unavailable for the specified nights")
        booking_id = self.booking_id_counter + 1
        for night in range(first_night, last_night + 1):
            self.rooms[room][night - 1] = booking_id
        self.bookings[booking_id] = {
            "room": room,
            "guest": guest,
            "first_night": first_night,
            "last_night": last_night,
            "status": "booked"
        }
        self.booking_id_counter += 1
        return booking_id

    def check_in(self, booking_id: int) -> None:
        if booking_id not in self.bookings:
