        if self.bookings[booking_id]["status"] != "checked_in":
            raise HotelError("Cannot check out for a booking that is not checked in")
        self.bookings[booking_id]["status"] = "checked_out"

    def get_status(self, booking_id: int) -> str:
        if booking_id not in self.bookings:
            raise KeyError("Booking ID not found")
        return self.bookings[booking_id]["status"]

    def get_booking_id(self, room: str, night: int) -> int | None:
