    def get_ious(self) -> list[tuple[str, str, int]]:
        return self.ious

    def get_owed(self, lender: str, borrower: str) -> int:
        owed = 0
        for l, b, a in self.ious:
            if l == lender and b == borrower:
                owed += a
        return owed
