                if dep not in self.jobs:
                    raise KeyError(f"Dependency {dep} not found")
        self.jobs[job_id] = {
            'priority': priority,
            'depends_on': depends_on if depends_on is not None else [],
            'completed': False
        }
        self.pending.append(job_id)

