        if job_id not in self.jobs:
            raise KeyError(f"Job {job_id} not found")
        if self.jobs[job_id]['completed']:
            raise QueueError(f"Job {job_id} already completed")
        if not all(self.jobs[dep]['completed'] for dep in self.jobs[job_id]['depends_on']):
            raise QueueError(f"Job {job_id} not ready to complete")
