    def __init__(self):
        self.items = {}
        self.item_order = []

    def add_item(self, name, quantity, use_by):
        if not name:
            raise ValueError("Empty name is not allowed")
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Quantity must be a positive integer")
        if not isinstance(use_by, int) or use_by < 0:
            raise ValueError("Use-by day must be a non-negative integer")

        if name not in self.items:
            self.items[name] = []
            self.item_order.append(name)

        self.items[name].append((use_by, quantity))

    def use_item(self, name, quantity):
