class RestaurantError(Exception):
    pass


class Restaurant:
    def __init__(self):
        self.menu = {}
        self.tables = {}

    def add_dish(self, name: str, price: int) -> None:
        if not name:
            raise ValueError("Dish name must be non-empty")
        if price <= 0:
            raise ValueError("Dish price must be greater than 0")
        if name in self.menu:
            raise RestaurantError("Dish already on the menu")
        self.menu[name] = price

    def open_table(self, table: str) -> None:
        if not table:
            raise ValueError("Table name must be non-empty")
        if table in self.tables:
            raise RestaurantError("Table is already open")
        self.tables[table] = []

    def order(self, table: str, dish: str, quantity: int) -> None:
        if table not in self.tables:
            raise KeyError("Table is not open")
        if dish not in self.menu:
            raise KeyError("Dish is not on the menu")
        if quantity <= 0:
            raise ValueError("Quantity must be greater than 0")
        for i, (d, q) in enumerate(self.tables[table]):
            if d == dish:
                self.tables[table][i] = (d, q + quantity)
                return
        self.tables[table].append((dish, quantity))

    def get_order(self, table: str) -> list[tuple[str, int]]:
        if table not in self.tables:
            raise KeyError("Table is not open")
        return self.tables[table]

    def get_bill(self, table: str) -> int:
        if table not in self.tables:
            raise KeyError("Table is not open")
        return sum(q * self.menu[d] for d, q in self.tables[table])

    def close_table(self, table: str) -> None:
        if table not in self.tables:
            raise KeyError("Table is not open")
        del self.tables[table]

    def get_open_tables(self) -> list[str]:
        return list(self.tables.keys())
