    def __init__(self, window: int):
        if not isinstance(window, int) or window <= 0:
            raise ValueError("Window must be an int greater than 0")
        self.window = window
        self.time = 0
        self.clients = {}
        self.receipt_number = 0

    def add_client(self, client_id: str, allowance: int) -> None:
        if not client_id:
            raise ValueError("Client id must not be empty")
        if not isinstance(allowance, int) or allowance <= 0:
            raise ValueError("Allowance must be an int greater than 0")
        if client_id in self.clients:
            raise LimiterError(f"Client {client_id} already registered")
        self.clients[client_id] = {
            'allowance': allowance,
            'current_window': 0,
            'remaining': allowance,
            'requests': []
        }

    def tick(self, steps: int = 1) -> None:
        if not isinstance(steps, int) or steps <= 0:
            raise ValueError("Steps must be an int greater than 0")
        self.time += steps
        current_window = self.time // self.window
        for client_id, client in self.clients.items():
            if client['current_window'] < current_window:
                client['current_window'] = current_window
                client['remaining'] = client['allowance']
                client['requests'] = []

    def request(self, client_id: str) -> int:
        if client_id not in self.clients:
            raise KeyError(f"Client {client_id} not registered")
        client = self.clients[client_id]
        if client['remaining'] <= 0:
            raise RateLimited(f"Client {client_id} rate limited")
        client['remaining'] -= 1
        client['requests'].append(self.receipt_number)
        self.receipt_number += 1
        return self.receipt_number

    def get_remaining(self, client_id: str) -> int:
        if client_id not in self.clients:
            raise KeyError(f"Client {client_id} not registered")
        return self.clients[client_id]['remaining']

    def get_time(self) -> int:
        return self.time

    def get_clients(self) -> list[str]:
        return list(self.clients.keys())
