    pass


class SoldOut(VendingError):
    pass


class NotEnoughCredit(VendingError):
    pass


class VendingMachine:
    def __init__(self):
        self.slots = {}
        self.credit = 0

    def add_slot(self, slot_id: str, price: int) -> None:
        if not slot_id:
            raise ValueError("Slot ID cannot be empty")
        if not isinstance(price, int) or price <= 0:
            raise ValueError("Price must be a positive integer")
        if slot_id in self.slots:
            raise VendingError(f"Slot {slot_id} already exists")
        self.slots[slot_id] = {'price': price, 'stock': 0}

    def restock(self, slot_id: str, count: int) -> None:
        if not isinstance(count, int) or count <= 0:
            raise ValueError("Count must be a positive integer")
        if slot_id not in self.slots:
            raise KeyError(f"Slot {slot_id} does not exist")
        self.slots[slot_id]['stock'] += count

    def insert_coins(self, amount: int) -> None:
        if not isinstance(amount, int) or amount <= 0:
            raise ValueError("Amount must be a positive integer")
        self.credit += amount

    def buy(self, slot_id: str) -> None:
        if slot_id not in self.slots:
            raise KeyError(f"Slot {slot_id} does not exist")
        if self.slots[slot_id]['stock'] == 0:
            raise SoldOut(f"Slot {slot_id} is sold out")
        if self.credit < self.slots[slot_id]['price']:
            raise NotEnoughCredit(f"Not enough credit for slot {slot_id}")
        self.slots[slot_id]['stock'] -= 1
        self.credit -= self.slots[slot_id]['price']

    def take_change(self) -> int:
        change = self.credit
        self.credit = 0
        return change

    def get_credit(self) -> int:
        return self.credit

    def get_stock(self, slot_id: str) -> int:
        if slot_id not in self.slots:
            raise KeyError(f"Slot {slot_id} does not exist")
        return self.slots[slot_id]['stock']

    def get_slots(self) -> list[str]:
        return list(self.slots.keys())
